-- how-much-does-a-small-business-website-cost
update public.ryzon_landing_blog set
  canonical_url = 'https://ryzonautomationllc.com/blog/how-much-does-a-small-business-website-cost',
  og_title = 'How Much Does a Small Business Website Cost?',
  og_description = 'What a small business website really costs, where the money goes, and how to choose between DIY, a one-time design fee and a monthly plan.',
  og_image = 'https://ryzonautomationllc.com/images/blog/how-much-does-a-small-business-website-cost.webp',
  author_slug = 'ryzon-automation-team',
  author_avatar_url = 'https://ryzonautomationllc.com/images/blog/author-ryzon.webp',
  author_bio = 'Ryzon Automation designs and manages websites for local small businesses, from $40/month with a $0 design fee. We write these guides to help owners get found on Google and turn visitors into calls. Based in Commerce Township, Michigan.',
  table_of_contents = '[{"id": "the-short-answer", "text": "The short answer", "level": 2, "content_description": "Most local businesses end up paying one of three ways: building it yourself on a website builder, paying a freelancer or agency a one-time design fee plus…"}, {"id": "what-you-are-paying-for", "text": "What you are actually paying for", "level": 2, "content_description": "Every website, whatever it costs, is made of the same parts: Design and build: the layout, the copy and making it work on phones."}, {"id": "three-ways-to-pay", "text": "The three ways to pay", "level": 2, "content_description": "Covers Do it yourself, One-time design fee and Monthly plan with no design fee."}, {"id": "do-it-yourself", "text": "Do it yourself", "level": 3, "content_description": "Website builders have low monthly fees, but the real cost is your time: picking a template, writing every page, sizing photos and fixing things when they break."}, {"id": "one-time-design-fee", "text": "One-time design fee", "level": 3, "content_description": "A freelancer or agency designs the site for a fixed project price, then you pay hosting separately."}, {"id": "monthly-plan", "text": "Monthly plan with no design fee", "level": 3, "content_description": "Some companies, including us, design the site for free and charge a monthly plan that covers hosting and care."}, {"id": "hidden-costs", "text": "Costs people forget", "level": 2, "content_description": "Domain renewals and business email."}, {"id": "how-to-choose", "text": "How to choose", "level": 2, "content_description": "Ask three questions: How much up-front money can the business spare?"}]'::jsonb,
  schema_markup = '{"@context": "https://schema.org", "@type": "WebPage", "@id": "https://ryzonautomationllc.com/blog/how-much-does-a-small-business-website-cost#webpage", "url": "https://ryzonautomationllc.com/blog/how-much-does-a-small-business-website-cost", "name": "How Much Does a Small Business Website Cost?", "description": "What a small business website really costs, where the money goes, and how to choose between DIY, a one-time design fee and a monthly plan.", "inLanguage": "en-US", "isPartOf": {"@id": "https://ryzonautomationllc.com/#website"}, "about": {"@id": "https://ryzonautomationllc.com/#business"}, "primaryImageOfPage": {"@type": "ImageObject", "url": "https://ryzonautomationllc.com/images/blog/how-much-does-a-small-business-website-cost.webp", "width": 1024, "height": 640}, "mainEntity": {"@id": "https://ryzonautomationllc.com/blog/how-much-does-a-small-business-website-cost#article"}}'::jsonb
where slug = 'how-much-does-a-small-business-website-cost';

