  table_of_contents = '[{"id": "why-owners-ask", "text": "Why owners ask this", "level": 2, "content_description": "A Facebook page is free, quick to set up, and many of your regulars already follow it."}, {"id": "what-social-does-well", "text": "What social pages do well", "level": 2, "content_description": "Posting news, specials and photos quickly."}, {"id": "what-a-website-does", "text": "What a website does that social cannot", "level": 2, "content_description": "Covers You own it, It reaches people who do not know you yet, It answers questions without a message and It makes you look established."}, {"id": "you-own-it", "text": "You own it", "level": 3, "content_description": "A social page lives on someone else''s platform."}, {"id": "people-who-do-not-know-you", "text": "It reaches people who do not know you yet", "level": 3, "content_description": "When someone searches for a service near them, search engines show websites far more prominently than social posts."}, {"id": "it-answers-questions", "text": "It answers questions without a message", "level": 3, "content_description": "Prices, service area, hours, what is included and how to book: a good website answers these on one page, so the customer can call ready to buy instead of…"}, {"id": "it-looks-established", "text": "It makes you look established", "level": 3, "content_description": "Many people check for a website before they call."}, {"id": "use-both", "text": "Use both, and link them", "level": 2, "content_description": "Keep posting on social, and point every profile to your website."}]'::jsonb,
  schema_markup = '{"@context": "https://schema.org", "@type": "WebPage", "@id": "https://ryzonautomationllc.com/blog/do-i-need-a-website-if-i-have-a-facebook-page#webpage", "url": "https://ryzonautomationllc.com/blog/do-i-need-a-website-if-i-have-a-facebook-page", "name": "Do I Need a Website If I Have a Facebook Page?", "description": "A Facebook page is not a website. What each one does for a local business, and why most do best with both.", "inLanguage": "en-US", "isPartOf": {"@id": "https://ryzonautomationllc.com/#website"}, "about": {"@id": "https://ryzonautomationllc.com/#business"}, "primaryImageOfPage": {"@type": "ImageObject", "url": "https://ryzonautomationllc.com/images/blog/do-i-need-a-website-if-i-have-a-facebook-page.webp", "width": 1024, "height": 640}, "mainEntity": {"@id": "https://ryzonautomationllc.com/blog/do-i-need-a-website-if-i-have-a-facebook-page#article"}}'::jsonb
