-- local-seo-for-small-business
update public.ryzon_landing_blog set
  canonical_url = 'https://ryzonautomationllc.com/blog/local-seo-for-small-business',
  og_title = 'Local SEO for Small Business: Step-by-Step',
  og_description = 'A plain-English local SEO guide for small businesses: set up your Google Business Profile, get reviews, fix your listings and get your website on Google.',
  og_image = 'https://ryzonautomationllc.com/images/blog/local-seo-for-small-business.webp',
  author_slug = 'ryzon-automation-team',
  author_avatar_url = 'https://ryzonautomationllc.com/images/blog/author-ryzon.webp',
  author_bio = 'Ryzon Automation designs and manages websites for local small businesses, from $40/month with a $0 design fee. We write these guides to help owners get found on Google and turn visitors into calls. Based in Commerce Township, Michigan.',
  table_of_contents = '[{"id": "what-is-local-seo", "text": "What local SEO actually means", "level": 2, "content_description": "When someone searches \"plumber near me\" or \"hair salon in Troy\", Google shows two kinds of results: a map with three businesses on it (the \"map pack\"), and…"}, {"id": "google-business-profile", "text": "Step 1: Claim and complete your Google Business Profile", "level": 2, "content_description": "Your Google Business Profile (it used to be called Google My Business) is the listing that shows in the map pack and on the right side of search results."}, {"id": "get-more-google-reviews", "text": "Step 2: Get more Google reviews (the right way)", "level": 2, "content_description": "Reviews help in two ways: they''re part of how Google judges prominence, and they''re the first thing a customer reads before calling you."}, {"id": "nap-consistency", "text": "Step 3: Make your name, address and phone match everywhere", "level": 2, "content_description": "SEO people call this NAP consistency: your business Name, Address and Phone number should be written the same way everywhere they appear online."}, {"id": "local-citations", "text": "Step 4: List your business on the sites that matter", "level": 2, "content_description": "A citation is any mention of your business details on another website."}, {"id": "get-your-website-on-google", "text": "Step 5: Get your website ready for local searches", "level": 2, "content_description": "Your Business Profile gets you into the map."}, {"id": "ai-search", "text": "What about AI search?", "level": 2, "content_description": "Google now shows AI-written summaries above many results, and more people ask tools like ChatGPT for recommendations."}, {"id": "local-seo-checklist", "text": "Your 30-day local SEO checklist", "level": 2, "content_description": "Week 1: claim, verify and fully complete your Google Business Profile, with photos."}, {"id": "faq", "text": "Frequently asked questions", "level": 2, "content_description": "Covers How much does local SEO cost for a small business?, Is local SEO worth it?, How long does local SEO take to work?, Can I rank on Google Maps without a website? and Is SEO dead now with AI?"}]'::jsonb,
  schema_markup = '{"@context": "https://schema.org", "@type": "WebPage", "@id": "https://ryzonautomationllc.com/blog/local-seo-for-small-business#webpage", "url": "https://ryzonautomationllc.com/blog/local-seo-for-small-business", "name": "Local SEO for Small Business: Step-by-Step", "description": "A plain-English local SEO guide for small businesses: set up your Google Business Profile, get reviews, fix your listings and get your website on Google.", "inLanguage": "en-US", "isPartOf": {"@id": "https://ryzonautomationllc.com/#website"}, "about": {"@id": "https://ryzonautomationllc.com/#business"}, "primaryImageOfPage": {"@type": "ImageObject", "url": "https://ryzonautomationllc.com/images/blog/local-seo-for-small-business.webp", "width": 1024, "height": 640}, "mainEntity": {"@id": "https://ryzonautomationllc.com/blog/local-seo-for-small-business#article"}}'::jsonb
where slug = 'local-seo-for-small-business';

