  author_bio = 'Ryzon Automation designs and manages websites for local small businesses, from $40/month with a $0 design fee. We write these guides to help owners get found on Google and turn visitors into calls. Based in Commerce Township, Michigan.',
  table_of_contents = '[{"id": "why-it-matters", "text": "Your website is your best salesperson", "level": 2, "content_description": "When a pipe bursts or the AC quits in July, people grab their phone, search, and call one of the first businesses that looks trustworthy."}, {"id": "above-the-fold", "text": "What visitors must see without scrolling", "level": 2, "content_description": "The top of your homepage, the part people see before they scroll, does most of the work."}, {"id": "pages-you-need", "text": "The pages every contractor website needs", "level": 2, "content_description": "Covers Home page, A page for each main service, Service area, Projects or gallery and more."}, {"id": "trust-signals", "text": "Trust signals that win the call", "level": 2, "content_description": "License and insurance: state it clearly, with license numbers."}, {"id": "by-trade", "text": "What each trade needs on its website", "level": 2, "content_description": "Covers Websites for plumbers, HVAC websites, Roofing websites, Electrician websites and Landscaping and lawn care websites."}, {"id": "contractor-seo", "text": "SEO for contractors: getting found, not just looking good", "level": 2, "content_description": "A beautiful website nobody finds won''t ring your phone."}, {"id": "mistakes", "text": "Common contractor website mistakes", "level": 2, "content_description": "A phone number that''s tiny, buried in the footer, or not tappable on a phone."}, {"id": "what-it-costs", "text": "What a contractor website costs", "level": 2, "content_description": "Prices range from a do-it-yourself builder subscription to thousands of dollars for a custom agency build, plus hosting and upkeep."}, {"id": "faq", "text": "Frequently asked questions", "level": 2, "content_description": "Covers How much does it cost to hire someone to design a contractor website?, How do I build a contractor website?, What is the 3-second rule in website design?, Should I use Wix or Squarespace for my contracting business? and How many pages should a contractor website have?"}]'::jsonb,
