-- website-maintenance-cost
update public.ryzon_landing_blog set
  canonical_url = 'https://ryzonautomationllc.com/blog/website-maintenance-cost',
  og_title = 'Website Maintenance Cost for Small Business',
  og_description = 'What small business website maintenance really costs: domain, hosting, security and updates, plus signs you are overpaying and what to ask first.',
  og_image = 'https://ryzonautomationllc.com/images/blog/website-maintenance-cost.webp',
  author_slug = 'ryzon-automation-team',
  author_avatar_url = 'https://ryzonautomationllc.com/images/blog/author-ryzon.webp',
  author_bio = 'Ryzon Automation designs and manages websites for local small businesses, from $40/month with a $0 design fee. We write these guides to help owners get found on Google and turn visitors into calls. Based in Commerce Township, Michigan.',
  table_of_contents = '[{"id": "short-answer", "text": "The short answer", "level": 2, "content_description": "Search for website maintenance costs and you''ll find ranges like \"$5 to $25,000 a month\"."}, {"id": "what-maintenance-includes", "text": "What website maintenance actually includes", "level": 2, "content_description": "Domain name: your address, like yourbusiness.com, renewed every year."}, {"id": "cost-breakdown", "text": "Cost breakdown, piece by piece", "level": 2, "content_description": "What each part usually costs: domain name, hosting, SSL, updates and backups, and content changes."}, {"id": "four-ways-to-pay", "text": "The four ways small businesses pay for maintenance", "level": 2, "content_description": "Covers 1. Do it yourself, 2. A freelancer, by the hour, 3. An agency care plan and 4. An all-in-one monthly website plan."}, {"id": "do-you-need-monthly-maintenance", "text": "Do websites need monthly maintenance?", "level": 2, "content_description": "Every website needs some upkeep, but how much depends on how it''s built: WordPress and other self-hosted platforms need regular software updates."}, {"id": "overpaying", "text": "Signs you''re overpaying", "level": 2, "content_description": "You pay a monthly maintenance fee but can''t name what was done last month."}, {"id": "red-flags", "text": "Red flags to check before you sign", "level": 2, "content_description": "Know who owns what."}, {"id": "redesign-or-maintain", "text": "When to redesign instead of maintaining", "level": 2, "content_description": "Sometimes paying to patch an old site is throwing good money after bad."}, {"id": "how-we-price", "text": "How we handle it", "level": 2, "content_description": "Ryzon Automation plans start at $40/month with a $0 design fee."}, {"id": "faq", "text": "Frequently asked questions", "level": 2, "content_description": "Covers How much should I pay someone to maintain my website?, Do websites need monthly maintenance?, How much does website hosting cost for a small business?, How much does a domain name cost? and Is it costly to maintain a website?"}]'::jsonb,
  schema_markup = '{"@context": "https://schema.org", "@type": "WebPage", "@id": "https://ryzonautomationllc.com/blog/website-maintenance-cost#webpage", "url": "https://ryzonautomationllc.com/blog/website-maintenance-cost", "name": "Website Maintenance Cost for Small Business", "description": "What small business website maintenance really costs: domain, hosting, security and updates, plus signs you are overpaying and what to ask first.", "inLanguage": "en-US", "isPartOf": {"@id": "https://ryzonautomationllc.com/#website"}, "about": {"@id": "https://ryzonautomationllc.com/#business"}, "primaryImageOfPage": {"@type": "ImageObject", "url": "https://ryzonautomationllc.com/images/blog/website-maintenance-cost.webp", "width": 1024, "height": 640}, "mainEntity": {"@id": "https://ryzonautomationllc.com/blog/website-maintenance-cost#article"}}'::jsonb
